-- Target: APEX 22.x (22.2, la ultima linea 22.x). p_release es MEJOR ESFUERZO,
-- NO verificado contra una instancia 22.x real (no hay una disponible en este
-- proyecto) -- el major.minor.0.00 esta confirmado real (existe la linea 22.2,
-- ver README), el numero de patch final es una referencia razonable, no un
-- valor confirmado. Antes de usarlo en produccion, correr en la instancia
-- destino: SELECT * FROM apex_release; y ajustar p_release si difiere -- en
-- la practica wwv_flow_api.import_begin no rechaza el import por esto (hay
-- plugins reales en produccion con p_release de APEX 5.x que se siguen
-- importando sin problema en instancias mucho mas nuevas).
-- El CUERPO del script (create_plugin/create_plugin_attribute/create_plugin_file)
-- es identico al de install_plugin_apex20.sql: verificado contra la documentacion
-- oficial de apex_plugin.t_dynamic_action/t_dynamic_action_render_result que no
-- cambio entre 20.1 y 24.2 (ver README).
--
-- Generic plugin, not tied to any company/schema. EDIT the 3 values below
-- (workspace id, application id, schema owner) before running -- the
-- numbers below are just placeholders, not real defaults. Recommended
-- alternative: install through the UI (install/manual_ui_install.md) or
-- Shared Components -> Plugins -> Import File once installed anywhere else
-- (APEX resolves the target workspace/app/owner automatically) -- see the
-- main README for why this is preferred over running this script directly.
begin
wwv_flow_api.import_begin (
 p_version_yyyy_mm_dd=>'2020.10.01'
,p_release=>'22.2.0.00.14'
,p_default_workspace_id=>0        -- REPLACE with your workspace id
,p_default_application_id=>0      -- REPLACE with your application id
,p_default_id_offset=>0
,p_default_owner=>'YOUR_SCHEMA'   -- REPLACE with your schema owner
);
end;
/

begin
wwv_flow_api.create_plugin(
 p_id=>wwv_flow_api.id(9201)
,p_plugin_type=>'DYNAMIC ACTION'
,p_name=>'BANCARD.POS_CLIENTE'
,p_display_name=>'POS Bancard - Cobro directo (cliente)'
,p_category=>'JAVASCRIPT'
,p_supported_ui_types=>'DESKTOP:'
,p_javascript_file_urls=>'#PLUGIN_FILES#pos_bancard_cliente.js'
,p_api_version=>1
,p_render_function=>'render'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function render',
'    ( p_dynamic_action in apex_plugin.t_dynamic_action',
'    , p_plugin         in apex_plugin.t_plugin',
'    )',
'return apex_plugin.t_dynamic_action_render_result',
'is',
'    l_result apex_plugin.t_dynamic_action_render_result;',
'begin',
'    l_result.javascript_function := ''bancardPosCliente.execute'';',
'    l_result.attribute_01 := p_dynamic_action.attribute_01;',
'    l_result.attribute_02 := p_dynamic_action.attribute_02;',
'    l_result.attribute_03 := p_dynamic_action.attribute_03;',
'    l_result.attribute_04 := p_dynamic_action.attribute_04;',
'    l_result.attribute_05 := p_dynamic_action.attribute_05;',
'    l_result.attribute_06 := p_dynamic_action.attribute_06;',
'    l_result.attribute_07 := p_dynamic_action.attribute_07;',
'    l_result.attribute_08 := p_dynamic_action.attribute_08;',
'    l_result.attribute_09 := p_dynamic_action.attribute_09;',
'    l_result.attribute_10 := p_dynamic_action.attribute_10;',
'    l_result.attribute_11 := p_dynamic_action.attribute_11;',
'    return l_result;',
'end render;'))
,p_help_text=>'Cobra con un terminal POS Bancard llamando directo desde el navegador del cajero (fetch al IP/puerto local del terminal), sin depender de ningun backend particular. Soporta todos los medios de pago del protocolo Bancard v1.5.0 (tarjeta contado/cuotas/debito forzado/credito forzado, QR, QR PIX, extraccion QR, canje de puntos, canje QR, billetera electronica). No mapea ni formatea nada a un esquema de datos especifico de una empresa: expone issuerId, monto y fecha crudos -cada app consumidora hace su propio mapeo/formato antes de guardar. Usa SweetAlert2 (empaquetado como archivo propio del plugin, no via CDN externo -asi funciona con Content Security Policy habilitado y sin depender de internet en la maquina del cajero) para el loader durante el eco y durante la espera/lectura del pago. Requiere que el navegador de la sucursal tenga deshabilitado chrome://flags/#block-insecure-private-network-requests y una extension tipo "Allow CORS", porque el terminal Bancard es HTTP plano y no manda headers CORS. Compatible con APEX 20.1 en adelante (verificado contra la documentacion oficial de apex_plugin.t_dynamic_action/t_dynamic_action_render_result para 20.1/22.1/23.2/24.2 -API estable, solo agrega campos nuevos, nunca quita).'
,p_version_identifier=>'3.1'
);

-- Atributo 1: item con la IP local del terminal POS
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(9211)
,p_plugin_id=>wwv_flow_api.id(9201)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>'Item: IP del POS'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>true
,p_is_translatable=>false
,p_help_text=>'Nombre del item que contiene la IP local del terminal Bancard.'
);

-- Atributo 2: item con el puerto del terminal POS
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(9212)
,p_plugin_id=>wwv_flow_api.id(9201)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>20
,p_prompt=>'Item: Puerto del POS'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>true
,p_is_translatable=>false
,p_help_text=>'Nombre del item que contiene el puerto del terminal Bancard.'
);

-- Atributo 3: item con el medio de pago
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(9213)
,p_plugin_id=>wwv_flow_api.id(9201)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_prompt=>'Item: Medio de Pago'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>true
,p_is_translatable=>false
,p_help_text=>'Nombre del item con el codigo del medio de pago: TARJETA_CONTADO, TARJETA_CUOTAS, TARJETA_DEBITO, TARJETA_CREDITO, QR, QR_PIX, EXTRACCION_QR, CANJE, CANJE_QR o BILLETERA.'
);

-- Atributo 4: item con el monto a cobrar
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(9215)
,p_plugin_id=>wwv_flow_api.id(9201)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>40
,p_prompt=>'Item: Monto'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>true
,p_is_translatable=>false
,p_help_text=>'Nombre del item con el monto a cobrar, como numero plano (sin separador de miles). Si tu app formatea el monto en pantalla, convertilo a numero antes de que dispare esta accion.'
);

-- Atributo 5: item con datos adicionales especificos del medio de pago (JSON)
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(9216)
,p_plugin_id=>wwv_flow_api.id(9201)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>5
,p_display_sequence=>50
,p_prompt=>'Item: Datos Adicionales (JSON, opcional)'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>false
,p_is_translatable=>false
,p_help_text=>'Item con un JSON crudo segun el medio de pago: {"cuotas":N,"plan":N} para TARJETA_CUOTAS/TARJETA_CREDITO, {"billetera":"ZIM","cuenta":"123456"} para BILLETERA, {"pix_payer_cpf":"...","pix_payer_phone":"..."} para QR_PIX, {"montoVuelto":N,"promotions":[...]} opcional para QR. Vacio si el medio no necesita datos extra.'
);

-- Atributo 6: item destino Nro Boleta/Autorizacion
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(9217)
,p_plugin_id=>wwv_flow_api.id(9201)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>6
,p_display_sequence=>60
,p_prompt=>'Item destino: Nro Boleta/Autorizacion'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>true
,p_is_translatable=>false
,p_help_text=>'Item donde se escribe, como string crudo, el nroBoleta (o codigoAutorizacion si no viene nroBoleta) devuelto por el POS.'
);

-- Atributo 7: item destino Issuer ID (crudo, sin mapear a ningun catalogo)
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(9218)
,p_plugin_id=>wwv_flow_api.id(9201)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>7
,p_display_sequence=>70
,p_prompt=>'Item destino: Issuer ID'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>true
,p_is_translatable=>false
,p_help_text=>'Item donde se escribe el issuerId crudo devuelto por el POS (ej. VD, MC, ZM). El plugin NO lo mapea a ningun codigo de marca de tarjeta interno -cada app hace su propio mapeo contra su propio catalogo, si lo necesita.'
);

-- Atributo 8: item destino Monto Cobrado (numero plano)
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(9219)
,p_plugin_id=>wwv_flow_api.id(9201)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>8
,p_display_sequence=>80
,p_prompt=>'Item destino: Monto Cobrado'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>true
,p_is_translatable=>false
,p_help_text=>'Item donde se escribe el monto cobrado como numero plano (sin formato). Cada app lo formatea segun su propia convencion antes de guardarlo.'
);

-- Atributo 9: item destino Fecha/Hora de la operacion (ISO 8601)
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(9220)
,p_plugin_id=>wwv_flow_api.id(9201)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>9
,p_display_sequence=>90
,p_prompt=>'Item destino: Fecha/Hora de la Operacion'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>true
,p_is_translatable=>false
,p_help_text=>'Item donde se escribe la fecha/hora actual en formato ISO 8601 (ej. 2026-07-22T19:13:07.342Z). Cada app la convierte al formato que necesite su proceso de guardado.'
);

-- Atributo 10: item destino Nro de Referencia (facturaNro)
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(9222)
,p_plugin_id=>wwv_flow_api.id(9201)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>10
,p_display_sequence=>100
,p_prompt=>'Item destino: Nro de Referencia'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>true
,p_is_translatable=>false
,p_help_text=>'Item donde se escribe el facturaNro generado client-side (Date.now()) para esta transaccion, el numero de referencia que el plugin le paso al POS.'
);

-- Atributo 11: item destino con la respuesta completa del POS (JSON crudo, opcional)
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(9223)
,p_plugin_id=>wwv_flow_api.id(9201)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>11
,p_display_sequence=>110
,p_prompt=>'Item destino: Resultado Completo (JSON, opcional)'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>false
,p_is_translatable=>false
,p_help_text=>'Item donde se escribe el JSON completo devuelto por el POS, para acceder a campos especificos de cada medio que no tienen item propio (saldo, montoComision, montoRs, nombreCliente, etc.).'
);
end;
/

